var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`सुरक्षित IF-THEN नियमों से अपने प्रिंटर को स्वचालित करें। डिफ़ॉल्ट रूप से बंद; हर नियम को स्वयं चालू करें।`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`अभी कोई नियम नहीं। नीचे एक जोड़ें, फिर तैयार होने पर उसे चालू करें।`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`नियम इंजन चालू है`}},off:{t:0,b:{t:2,i:[{t:3}],s:`नियम इंजन बंद है`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`चालू करें`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`बंद करें`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`जब तक इंजन और अलग-अलग नियम दोनों चालू न हों, कुछ भी नहीं चलता।`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`जब कोई प्रिंट पूरा हो`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`जब प्रिंटर में त्रुटि हो`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`जब कोई हीटर इससे ऊपर जाए`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`जब कोई हीटर इससे नीचे गिरे`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`एक सूचना लॉग करें`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`एक g-code कमांड चलाएँ`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`चालू`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`बंद`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`संपादित करें`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`हटाएँ`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`नियम हटाएँ`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`नियम का नाम`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`उदा. प्रिंट के बाद हीटर बंद`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`यदि (ट्रिगर)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`तो (कार्रवाई)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`हीटर`}},value:{t:0,b:{t:2,i:[{t:3}],s:`तापमान (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`संदेश`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`नियम लॉग में दिखाया गया`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`उदा. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`नियम सहेजें`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`रद्द करें`}},add:{t:0,b:{t:2,i:[{t:3}],s:`एक नियम जोड़ें`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`हाल की गतिविधि`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`सूचित किया`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`g-code चलाया`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`छोड़ दिया (प्रिंटर व्यस्त)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`त्रुटि`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`गाइड`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`नियम इंजन गाइड`}},close:{t:0,b:{t:2,i:[{t:3}],s:`बंद करें`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`नियम इंजन क्या है?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`यह प्रिंटर पर नज़र रखता है और आपके द्वारा तय की गई कोई शर्त पूरी होने पर एक कार्रवाई चलाता है - उदाहरण के लिए, प्रिंट पूरा होने पर एक नोट लॉग करना, या हीटर बंद कर देना। हर नियम है यदि (एक ट्रिगर) तो (एक कार्रवाई)।`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`यह सुरक्षित कैसे रहता है`}},body:{t:0,b:{t:2,i:[{t:3}],s:`इंजन डिफ़ॉल्ट रूप से बंद रहता है और हर नियम को अलग-अलग चालू करना ज़रूरी है, ताकि कुछ भी अचानक न चले। कोई नियम तब एक बार चलता है जब उसकी शर्त पहली बार सही होती है। G-code कार्रवाइयाँ केवल तभी चलती हैं जब प्रिंटर निष्क्रिय हो - प्रिंट के दौरान उन्हें अस्वीकार कर दिया जाता है - और हर परिणाम लॉग किया जाता है।`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`शब्दावली`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`ट्रिगर`}},def:{t:0,b:{t:2,i:[{t:3}],s:`वह शर्त जो किसी नियम को शुरू करती है, उदा. प्रिंट का पूरा होना या किसी हीटर का तापमान सीमा पार करना।`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`कार्रवाई`}},def:{t:0,b:{t:2,i:[{t:3}],s:`नियम के चलने पर वह जो करता है: एक सूचना लॉग करना, या एक g-code कमांड चलाना (केवल निष्क्रिय रहते हुए)।`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`चालू`}},def:{t:0,b:{t:2,i:[{t:3}],s:`वह नियम जो चालू किया गया है। बंद नियम रखे जाते हैं पर कभी नहीं चलते।`}}}}}}};export{e as default};